%% A1 Portrait — Dark-Mode Dashboard Aesthetic
%% Frontier AI Models: Intelligence, Speed & Cost
%% Artificial Analysis Intelligence Index v4.0

\documentclass{article}
\usepackage[paperwidth=594mm,paperheight=841mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\usepackage{array}
\usepackage{booktabs}
\usepackage{colortbl}
\usepackage{tikz}
\usetikzlibrary{calc,pgfplots.fillbetween}
\usepackage{pgfplots}
\pgfplotsset{compat=1.18}
\pagestyle{empty}

%% ── Dark-Mode Color Palette ──────────────────────────────────────────────────
\definecolor{bgposter}{HTML}{141820}       % near-black charcoal
\definecolor{bgcard}{HTML}{1E2530}         % card background (slightly lighter)
\definecolor{bgcard2}{HTML}{222A38}        % alternate card background
\definecolor{bgcard3}{HTML}{1A2235}        % darker card for contrast
\definecolor{electric}{HTML}{3B9EFF}       % electric blue – primary accent
\definecolor{teal}{HTML}{2DD4BF}           % teal – secondary accent
\definecolor{amber}{HTML}{FBBF24}          % warm amber – tertiary accent
\definecolor{coral}{HTML}{F87171}          % coral – highlight/warning
\definecolor{stripeblue}{HTML}{2563EB}     % border stripe blue
\definecolor{stripeteal}{HTML}{0D9488}     % border stripe teal
\definecolor{stripeamber}{HTML}{D97706}    % border stripe amber
\definecolor{textprimary}{HTML}{F1F5F9}    % near-white body text
\definecolor{textsecondary}{HTML}{94A3B8}  % muted text
\definecolor{textmuted}{HTML}{64748B}      % very muted
\definecolor{divider}{HTML}{2D3748}        % subtle divider line
\definecolor{statbg}{HTML}{0F172A}         % stat callout background
\definecolor{gembg}{HTML}{162032}          % gemini card tint
\definecolor{gptbg}{HTML}{12201E}          % gpt card tint
\definecolor{claudebg}{HTML}{1C1A2A}       % claude card tint

\pagecolor{bgposter}
\color{textprimary}

%% ── List styling ─────────────────────────────────────────────────────────────
\setlist[itemize]{leftmargin=22pt, itemsep=5pt, parsep=1pt, topsep=2pt,
  label={\color{teal}$\bullet$}}
\setlist[enumerate]{leftmargin=22pt, itemsep=5pt, parsep=1pt, topsep=2pt,
  label={\color{electric}\bfseries\arabic*.}}

%% ── Card Styles ──────────────────────────────────────────────────────────────
\tcbset{
  darkcard/.style={
    enhanced, arc=4pt, boxrule=0pt, colback=bgcard,
    borderline west={4pt}{0pt}{electric},
    left=14pt, right=12pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{32}{38}\selectfont\bfseries\color{electric},
    coltitle=electric, colbacktitle=bgcard3,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=1pt, titlerule style={electric!30},
    valign=top,
    drop shadow={opacity=0.4, color=black},
  },
  tealcard/.style={
    enhanced, arc=4pt, boxrule=0pt, colback=bgcard2,
    borderline west={4pt}{0pt}{teal},
    left=14pt, right=12pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{32}{38}\selectfont\bfseries\color{teal},
    coltitle=teal, colbacktitle=bgcard3,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=1pt, titlerule style={teal!30},
    valign=top,
    drop shadow={opacity=0.4, color=black},
  },
  ambercard/.style={
    enhanced, arc=4pt, boxrule=0pt, colback=bgcard,
    borderline west={4pt}{0pt}{amber},
    left=14pt, right=12pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{32}{38}\selectfont\bfseries\color{amber},
    coltitle=amber, colbacktitle=bgcard3,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=1pt, titlerule style={amber!30},
    valign=top,
    drop shadow={opacity=0.4, color=black},
  },
  herocard/.style={
    enhanced, arc=4pt, boxrule=0pt, colback=bgcard3,
    borderline west={6pt}{0pt}{electric},
    borderline north={2pt}{0pt}{electric!40},
    left=14pt, right=12pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{32}{38}\selectfont\bfseries\color{textprimary},
    coltitle=textprimary, colbacktitle=stripeblue,
    toptitle=6pt, bottomtitle=6pt,
    valign=top,
    drop shadow={opacity=0.5, color=black},
  },
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=2, rows=32, spacing=3mm},
]

%% ══════════════════════════════════════════════════════════════════════════════
%% TITLE BAR
%% ══════════════════════════════════════════════════════════════════════════════
\posterbox[
  enhanced, arc=0pt, boxrule=0pt,
  colback=bgposter,
  borderline south={2pt}{0pt}{electric!50},
  left=20pt, right=20pt, top=10pt, bottom=10pt,
  halign=center, valign=center,
]{name=title, column=1, span=2, between=top and row4}{
  {\fontsize{18}{22}\selectfont\bfseries\color{textsecondary}
    ARTIFICIAL ANALYSIS INTELLIGENCE INDEX v4.0}\\[6pt]
  {\fontsize{54}{64}\selectfont\bfseries\color{textprimary}
    Frontier AI Models Compared}\\[4pt]
  {\fontsize{42}{50}\selectfont\bfseries\color{electric}
    Intelligence · Speed · Cost}\\[8pt]
  {\fontsize{18}{24}\selectfont\color{textsecondary}
    A data-driven comparison of 10 leading language models across three critical dimensions%
  }
}

%% ══════════════════════════════════════════════════════════════════════════════
%% STATS BANNER — 5 headline callouts
%% ══════════════════════════════════════════════════════════════════════════════
\posterbox[
  enhanced, arc=0pt, boxrule=0pt,
  colback=statbg,
  borderline north={2pt}{0pt}{electric!30},
  borderline south={2pt}{0pt}{divider},
  left=8pt, right=8pt, top=8pt, bottom=8pt,
  valign=center,
]{name=stats, column=1, span=2, between=row4 and row9}{
  \centering
  \begin{minipage}[c]{0.185\linewidth}\centering
    \colorbox{bgcard3}{\parbox[c][46pt][c]{0.90\linewidth}{\centering
      {\fontsize{38}{44}\selectfont\bfseries\color{electric}57}\\[1pt]
      {\fontsize{15}{18}\selectfont\color{textsecondary}AA Index Peak}
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.185\linewidth}\centering
    \colorbox{bgcard3}{\parbox[c][46pt][c]{0.90\linewidth}{\centering
      {\fontsize{38}{44}\selectfont\bfseries\color{teal}206}\\[1pt]
      {\fontsize{15}{18}\selectfont\color{textsecondary}tokens/sec max}
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.185\linewidth}\centering
    \colorbox{bgcard3}{\parbox[c][46pt][c]{0.90\linewidth}{\centering
      {\fontsize{38}{44}\selectfont\bfseries\color{amber}33\texttimes}\\[1pt]
      {\fontsize{15}{18}\selectfont\color{textsecondary}price range}
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.185\linewidth}\centering
    \colorbox{bgcard3}{\parbox[c][46pt][c]{0.90\linewidth}{\centering
      {\fontsize{38}{44}\selectfont\bfseries\color{coral}\$0.30}\\[1pt]
      {\fontsize{15}{18}\selectfont\color{textsecondary}cheapest/1M tok}
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.185\linewidth}\centering
    \colorbox{bgcard3}{\parbox[c][46pt][c]{0.90\linewidth}{\centering
      {\fontsize{38}{44}\selectfont\bfseries\color{coral}\$10.00}\\[1pt]
      {\fontsize{15}{18}\selectfont\color{textsecondary}premium/1M tok}
    }}
  \end{minipage}
}

%% ══════════════════════════════════════════════════════════════════════════════
%% COL 1 — Intelligence Rankings
%% ══════════════════════════════════════════════════════════════════════════════
\posterbox[darkcard, title={Intelligence Rankings}
]{name=intel, column=1, between=row9 and row20}{
  \fontsize{16}{22}\selectfont\color{textsecondary}
  AA Index v4.0 · 10 benchmarks · coding, reasoning, knowledge\par\vspace{6pt}
  %% ── Intelligence bar chart rendered via tikz ──
  \begin{tikzpicture}
  \fontsize{14}{17}\selectfont
  \pgfplotsset{
    axis line style={color=divider},
    tick style={color=divider},
  }
  \begin{axis}[
    xbar,
    width=\linewidth, height=6.2cm,
    bar width=9pt,
    xmin=0, xmax=70,
    xtick={0,10,20,30,40,50,60,70},
    xticklabel style={font=\fontsize{12}{14}\selectfont, color=textsecondary},
    yticklabels={
      {gpt-oss-120B},
      {DeepSeek V3.2},
      {Gemini 3 Flash},
      {Grok 4.20},
      {GLM-5.1},
      {C.\ Sonnet 4.6},
      {Muse Spark},
      {C.\ Opus 4.6},
      {GPT-5.4 xhigh},
      {Gemini 3.1 Pro},
    },
    ytick={1,2,...,10},
    yticklabel style={font=\fontsize{12}{15}\selectfont, color=textprimary, align=right},
    axis background/.style={fill=bgcard},
    enlarge y limits=0.07,
    grid=x, grid style={dashed, color=divider},
    tick align=outside,
    axis x line=bottom,
    axis y line=left,
    clip=false,
  ]
  % Budget/slow models (muted color)
  \addplot[xbar, fill=textmuted!60, draw=none] coordinates {
    (33,1)  % gpt-oss-120B
    (42,2)  % DeepSeek V3.2
  };
  % Mid-tier (teal)
  \addplot[xbar, fill=teal!70, draw=none] coordinates {
    (46,3)  % Gemini 3 Flash
    (49,4)  % Grok 4.20
    (51,5)  % GLM-5.1
    (52,6)  % Claude Sonnet 4.6
    (52,7)  % Muse Spark
  };
  % Top-tier (electric blue)
  \addplot[xbar, fill=electric!90, draw=none] coordinates {
    (53,8)  % Claude Opus 4.6
  };
  % Leaders (amber for tied leaders)
  \addplot[xbar, fill=amber!90, draw=none] coordinates {
    (57,9)  % GPT-5.4
    (57,10) % Gemini 3.1 Pro
  };
  % Score labels
  \node[anchor=west, font=\fontsize{12}{14}\selectfont, color=textsecondary] at (axis cs:33,1) {\,33};
  \node[anchor=west, font=\fontsize{12}{14}\selectfont, color=textsecondary] at (axis cs:42,2) {\,42};
  \node[anchor=west, font=\fontsize{12}{14}\selectfont, color=teal]       at (axis cs:46,3) {\,46};
  \node[anchor=west, font=\fontsize{12}{14}\selectfont, color=teal]       at (axis cs:49,4) {\,49};
  \node[anchor=west, font=\fontsize{12}{14}\selectfont, color=teal]       at (axis cs:51,5) {\,51};
  \node[anchor=west, font=\fontsize{12}{14}\selectfont, color=teal]       at (axis cs:52,6) {\,52};
  \node[anchor=west, font=\fontsize{12}{14}\selectfont, color=teal]       at (axis cs:52,7) {\,52};
  \node[anchor=west, font=\fontsize{12}{14}\selectfont, color=electric]   at (axis cs:53,8) {\,53};
  \node[anchor=west, font=\fontsize{13}{15}\selectfont\bfseries, color=amber] at (axis cs:57,9)  {\,\textbf{57}};
  \node[anchor=west, font=\fontsize{13}{15}\selectfont\bfseries, color=amber] at (axis cs:57,10) {\,\textbf{57}};
  \end{axis}
  \end{tikzpicture}

  \vspace{4pt}
  \colorbox{bgcard3}{\parbox{0.95\linewidth}{\fontsize{14}{19}\selectfont\color{textprimary}
    \textcolor{amber}{\bfseries Tied leaders:} Gemini 3.1 Pro Preview \& GPT-5.4 both score \textcolor{amber}{\bfseries 57} —
    a 24-point gap above the budget tier.
  }}\vspace{2pt}

  \colorbox{bgcard3}{\parbox{0.95\linewidth}{\fontsize{14}{19}\selectfont\color{textprimary}
    \textcolor{electric}{\bfseries Benchmarks:} GDPval-AA · Terminal-Bench Hard ·
    SciCode · GPQA Diamond · HLE · IFBench · τ²-Bench · AA-LCR · AA-Omniscience · CritPt
  }}
}

%% ══════════════════════════════════════════════════════════════════════════════
%% COL 1 — Speed Comparison
%% ══════════════════════════════════════════════════════════════════════════════
\posterbox[tealcard, title={Output Speed  \normalfont\fontsize{20}{24}\selectfont\color{textsecondary}(tokens / sec)}
]{name=speed, column=1, between=row20 and row29}{
  \fontsize{16}{22}\selectfont\color{textsecondary}
  \textcolor{coral}{\bfseries Fastest $\neq$ Smartest} — speed and intelligence are inversely correlated at the extremes.\par\vspace{6pt}

  \begin{tikzpicture}
  \fontsize{14}{17}\selectfont
  \begin{axis}[
    xbar,
    width=\linewidth, height=5.6cm,
    bar width=9pt,
    xmin=0, xmax=230,
    xtick={0,50,100,150,200},
    xticklabel style={font=\fontsize{12}{14}\selectfont, color=textsecondary},
    yticklabels={
      {DeepSeek V3.2},
      {C.\ Opus 4.6},
      {GLM-5.1},
      {C.\ Sonnet 4.6},
      {GPT-5.4 xhigh},
      {Gemini 3.1 Pro},
      {Gemini 3 Flash},
      {Grok 4.20},
      {Nemotron 3},
      {gpt-oss-120B},
    },
    ytick={1,2,...,10},
    yticklabel style={font=\fontsize{12}{15}\selectfont, color=textprimary},
    axis background/.style={fill=bgcard2},
    enlarge y limits=0.07,
    grid=x, grid style={dashed, color=divider},
    tick align=outside,
    axis x line=bottom,
    axis y line=left,
    clip=false,
  ]
  % Intelligence leaders — slow (muted)
  \addplot[xbar, fill=textmuted!50, draw=none] coordinates {
    (31,1)  % DeepSeek
    (40,2)  % Claude Opus
    (40,3)  % GLM-5.1
    (48,4)  % Claude Sonnet
    (72,5)  % GPT-5.4
  };
  % Mid speed
  \addplot[xbar, fill=teal!65, draw=none] coordinates {
    (129,6) % Gemini Pro
    (149,7) % Gemini Flash
    (162,8) % Grok
  };
  % Top speed — budget models
  \addplot[xbar, fill=coral!80, draw=none] coordinates {
    (193,9)  % Nemotron
    (206,10) % gpt-oss-120B
  };
  % Labels
  \node[anchor=west, font=\fontsize{12}{14}\selectfont, color=textsecondary] at (axis cs:31,1)  {\,31};
  \node[anchor=west, font=\fontsize{12}{14}\selectfont, color=textsecondary] at (axis cs:40,2)  {\,40};
  \node[anchor=west, font=\fontsize{12}{14}\selectfont, color=textsecondary] at (axis cs:40,3)  {\,40};
  \node[anchor=west, font=\fontsize{12}{14}\selectfont, color=textsecondary] at (axis cs:48,4)  {\,48};
  \node[anchor=west, font=\fontsize{12}{14}\selectfont, color=textsecondary] at (axis cs:72,5)  {\,72};
  \node[anchor=west, font=\fontsize{12}{14}\selectfont, color=teal]          at (axis cs:129,6) {\,129};
  \node[anchor=west, font=\fontsize{12}{14}\selectfont, color=teal]          at (axis cs:149,7) {\,149};
  \node[anchor=west, font=\fontsize{12}{14}\selectfont, color=teal]          at (axis cs:162,8) {\,162};
  \node[anchor=west, font=\fontsize{13}{15}\selectfont\bfseries, color=coral] at (axis cs:193,9)  {\,\textbf{193}};
  \node[anchor=west, font=\fontsize{13}{15}\selectfont\bfseries, color=coral] at (axis cs:206,10) {\,\textbf{206}};
  \end{axis}
  \end{tikzpicture}

  \vspace{4pt}
  \colorbox{bgcard3}{\parbox{0.95\linewidth}{\fontsize{14}{19}\selectfont\color{textprimary}
    \textcolor{coral}{\bfseries gpt-oss-120B} leads at \textbf{206 tok/s} — nearly \textbf{7$\times$} faster than
    DeepSeek V3.2 (31 tok/s), yet ranks \emph{last} in intelligence.
  }}
}

%% ══════════════════════════════════════════════════════════════════════════════
%% COL 1 — Methodology note
%% ══════════════════════════════════════════════════════════════════════════════
\posterbox[ambercard, title={About the Index}
]{name=method, column=1, between=row29 and bottom}{
  \fontsize{15}{20}\selectfont\color{textprimary}
  The \textcolor{amber}{\bfseries Artificial Analysis Intelligence Index v4.0}
  aggregates \textbf{10 independent evaluations} using standardized conditions:\par\vspace{4pt}
  \begin{itemize}[itemsep=3pt]
    \item Coding: \textbf{GDPval-AA}, \textbf{Terminal-Bench Hard}
    \item Scientific: \textbf{SciCode}, \textbf{GPQA Diamond}
    \item Knowledge: \textbf{AA-Omniscience}, \textbf{HLE}
    \item Agentic: \textbf{τ²-Bench Telecom}, \textbf{AA-LCR}
    \item Instruction: \textbf{IFBench}, \textbf{CritPt}
  \end{itemize}\vspace{4pt}
  {\fontsize{14}{18}\selectfont\color{textsecondary}
    Source: artificialanalysis.ai \quad Data: April 2026}
}

%% ══════════════════════════════════════════════════════════════════════════════
%% COL 2 — Pricing Landscape
%% ══════════════════════════════════════════════════════════════════════════════
\posterbox[ambercard, title={Pricing Landscape  \normalfont\fontsize{20}{24}\selectfont\color{textsecondary}(USD / 1M tokens, blended)}
